<?php
namespace App\Controllers;
use App\Models\AdminModel;
use Config\Database;
final class AdminDashboardController extends BaseController { public function index(): string { $db=Database::connect();$statuses=['pending','under_review','resolved','rejected'];$requestCounts=array_fill_keys($statuses,0);foreach($db->table('verification_assistance_requests')->select('status, COUNT(*) AS total')->groupBy('status')->get()->getResultArray() as $row){if(array_key_exists($row['status'],$requestCounts))$requestCounts[$row['status']]=(int)$row['total'];}return view('admin/dashboard',['title'=>'Dashboard','adminUser'=>(new AdminModel())->select('full_name')->find((int)session()->get('admin_id')),'total'=>$db->table('students')->countAllResults(),'enrolled'=>$db->table('students')->where('enrollment_status','enrolled')->countAllResults(),'successful'=>$db->table('verification_logs')->where('verification_result','verified')->countAllResults(),'unsuccessful'=>$db->table('verification_logs')->where('verification_result !=','verified')->countAllResults(),'requests'=>array_sum($requestCounts),'requestCounts'=>$requestCounts,'recentVerifications'=>$db->table('verification_logs')->select('requested_at, verification_result, response_category')->orderBy('requested_at','DESC')->orderBy('id','DESC')->limit(6)->get()->getResultArray(),'recentRequests'=>$db->table('verification_assistance_requests')->select('id, student_id, full_name, status, created_at')->orderBy('created_at','DESC')->orderBy('id','DESC')->limit(6)->get()->getResultArray()]);}}
